use vstd::prelude::*;

verus! {

fn imag(val: Vec<(f64, f64)>) -> Vec<f64>
    ensures
        // 1. The output has the same length as the input
        result.len() == val.len(),
        // 2. For every index i, result[i] equals the imaginary part of val[i]
        forall|i: nat| i < val.len() ==> result[i] == val[i].1,
        // 3. If the imaginary part is 0.0, the output is 0.0
        forall|i: nat| i < val.len() && val[i].1 == 0.0 ==> result[i] == 0.0,
        // 4. If the input is not the zero complex, result[i] equals the imaginary part
        forall|i: nat| i < val.len() && (val[i].0 != 0.0 || val[i].1 != 0.0) ==> result[i] == val[i].1,
{
    // Build a new Vec<f64> by extracting the second component of each pair
    let mut result: Vec<f64> = Vec::new();
    // Pre‐allocate to avoid re‐allocation
    result.reserve(val.len());
    let mut i: usize = 0;

    // Loop over all indices
    while i < val.len()
        invariant
            // index remains in bounds
            i <= val.len(),
            // result.len() tracks i
            result.len() == i,
            // for all already‐processed j < i, result[j] == val[j].1
            forall|j: nat| j < i ==> result[j] == val[j].1,
            // and those extra properties hold on processed prefix
            forall|j: nat| j < i && val[j].1 == 0.0 ==> result[j] == 0.0,
            forall|j: nat| j < i && (val[j].0 != 0.0 || val[j].1 != 0.0) ==> result[j] == val[j].1,
        decreases val.len() - i,
    {
        // extract the imaginary part
        let imag_part: f64 = val[i].1;
        // push it onto the result
        result.push(imag_part);
        // show that the newly pushed element is correct
        assert(result[i] == val[i].1);
        assert(result[i] == imag_part);
        // advance
        i += 1;
    }

    result
}

} // end of verus! 

